        # All subsequent groups must be exactly 3 digits
        for g in groups[1:]:
            if len(g) != 3:
                raise ValueError("Invalid grouping")

    integer_part_cleaned = integer_part_str.replace(",", "")
    if not integer_part_cleaned.isdigit():
        raise ValueError("Invalid integer part")

    integer_val = int(integer_part_cleaned)

    if fractional_part_str:
