from typing import Any, Dict, Iterable, List, Mapping, Optional, Sequence, Set, Tuple, Union


def round_div(numerator: int, denominator: int, mode: str = "half_up") -> int:
    """
    Divide two integers and round the quotient to an integer, using exact integer
    arithmetic (no floats). `denominator` must be positive.

    Rounding modes:
      * "half_up"   - round to the nearest integer; exact halves are rounded away from zero (default)
      * "half_even" - round to the nearest integer; exact halves go to the even neighbour
      * "floor"     - round towards negative infinity
      * "ceiling"   - round towards positive infinity

    Raises ValueError if `denominator` <= 0 or `mode` is not one of the names above.

    Examples:
        round_div(7, 2) == 4
        round_div(5, 2, "half_even") == 2
        round_div(-7, 2, "floor") == -4
    """
    if denominator <= 0:
        raise ValueError("denominator must be positive")

    if mode not in {"half_up", "half_even", "floor", "ceiling"}:
        raise ValueError(f"Unknown rounding mode: {mode}")

    if mode == "floor":
        return numerator // denominator

    if mode == "ceiling":
        # ceiling(a/b) = -floor(-a/b)
        return -(-numerator // denominator)

    # For half-based rounding, use absolute values to handle 'away from zero'
    # and 'even' consistently, then restore the sign.
    sign = 1 if numerator >= 0 else -1
    abs_num = abs(numerator)
    q_abs = abs_num // denominator
    r_abs = abs_num % denominator

    if r_abs == 0:
        return sign * q_abs

    if mode == "half_up":
        # Away from zero: if 2*r >= d, increment absolute quotient
        if 2 * r_abs >= denominator:
            return sign * (q_abs + 1)
        else:
            return sign * q_abs
    elif mode == "half_even":
        if 2 * r_abs == denominator:
            # Exactly half: round to even absolute quotient
            if q_abs % 2 == 0:
                return sign * q_abs
            else:
                return sign * (q_abs + 1)
        elif 2 * r_abs > denominator:
            return sign * (q_abs + 1)
        else:
            return sign * q_abs

    return numerator // denominator
